function footerNavigation(prefix:string):Section{return section(prefix+'-navigation','actions','',{layout:'inline',visual:{actionFormat:'rows'},content:{actions:[['Início',prefix+'-actions'],['Produtos',prefix+'-products'],['Sobre',prefix+'-about'],['Localização',prefix+'-location'],['Contato',prefix+'-whatsapp']].map(([label,sectionId],i)=>({id:prefix+'-nav-'+i,kind:'custom',label,message:'',destination:'section',sectionId}))}})}

function boutiqueModel(base:Bio,variant:'charmme-moda-feminina'|'lumiere-boutique'):Template{
 const pink=variant==='charmme-moda-feminina',prefix=pink?'charmme':'lumiere',name=pink?'Charmme':'Lumière',model=bellaModa(base),bio=model.bio
 bio.id=variant;bio.layoutPreset=variant;bio.name=name;bio.tagline=pink?'MODA FEMININA':'BOUTIQUE';bio.headline=pink?'Moda que\nvaloriza você!':'Moda que\nrealça a sua\nessência.';bio.description='Peças modernas, elegantes e versáteis para mulheres que vivem o seu melhor todos os dias.';bio.cover=images.look;bio.color=pink?'#ed0063':'#ecc38e';bio.heroVisual={minHeight:410,imagePositionX:78,imagePositionY:30,overlay:60,logoSize:40};bio.appearance={...bio.appearance!,theme:pink?'light':'dark',font:'sans',background:pink?'#fff8fa':'#0c0b09',text:pink?'#111111':'#ffffff',panel:pink?'#fce8ef':'#221d17',secondary:pink?'#f5b7d0':'#cfaa76',highlight:bio.color,border:pink?'#f2c5d8':'#64513c'};bio.textVisual={name:{font:pink?'serif':'serif',fontSize:pink?49:38,weight:'regular'},headline:{font:'serif',fontSize:31,lineHeight:110},description:{fontSize:13,lineHeight:140}};bio.identity={brandColors:[bio.color,bio.appearance.background!,bio.appearance.text!],logoPalette:[bio.color,bio.appearance.background!]}
 // Keep all owners, actions and destinations in the same persistent shared schema.
 bio.sections=JSON.parse(JSON.stringify(bio.sections).replaceAll('bella-',prefix+'-'))
 bio.actions=[{id:prefix+'-hero-action',kind:'custom',icon:'link',label:'Ver coleção',message:'',destination:'section',sectionId:prefix+'-collections'}]
 const find=(kind:Section['kind'])=>bio.sections.find(s=>s.kind===kind)!,byId=(suffix:string)=>bio.sections.find(s=>s.id===prefix+'-'+suffix)!
 const main=find('actions');main.visual={columns:4,iconSize:44,glyphSize:31,gap:8};main.content={actions:actions(prefix)}
 const categories=find('categories');categories.title='Nossas Categorias';categories.visual={columns:4,mediaAspect:100,gap:8};categories.content={highlights:[['Vestidos',images.dress],['Conjuntos',images.look],['Blusas',images.bella],['Calças',images.jeans]].map(([label,image],i)=>({id:prefix+'-category-'+i,label,image,caption:'Ver coleção'}))}
 const first=byId('banner');first.title='Nova Coleção\nPrimavera';first.text='Leveza, estilo e autenticidade para o seu dia a dia.';first.ctaLabel='Confira agora';first.visual={mediaAspect:230,mediaPlacement:'background',panel:pink?'#f7c8d8':'#ead0b1',text:'#111111',imagePositionX:80};first.image=images.bella
 const products=find('products');products.content={items:[['Vestido Midi Elegance','R$ 159,90',images.dress],['Conjunto Alfaiataria','R$ 199,90',images.look],['Blusa Canelada','R$ 69,90',images.bella],['Calça Wide Leg','R$ 149,90',images.jeans],['Vestido Longo','R$ 179,90',images.dress],['Conjunto Linho','R$ 189,90',images.look]].map(([title,price,image],i)=>({id:prefix+'-item-'+i,title,price,image,description:'',action:{id:prefix+'-buy-'+i,kind:'whatsapp',icon:'cart',label:'Comprar',message:'Olá! Tenho interesse em '+title}}))};products.visual={columns:3,mediaAspect:108}
 const second=byId('elegance');second.title=pink?'Acessórios\nque completam\nseu look':'Elegância\nem cada\ndetalhe';second.text=pink?'Detalhes que valorizam o seu estilo.':'Peças que acompanham você em todos os momentos.';second.ctaLabel=pink?'Ver acessórios':'Ver coleção';second.image=photo('photo-1548036328-c9fa89d128fa');second.visual={mediaAspect:300,mediaPlacement:'background',panel:pink?'#840b30':'#2d2114',text:pink?'#ffffff':'#ecc38e'}
 bio.sections=bio.sections.filter(s=>s!==second);bio.sections.splice(bio.sections.indexOf(products)+1,0,second)
 const benefits=byId('benefits');benefits.visual={columns:4};benefits.content={benefits:['Qualidade Premium|em cada peça','Moda Atual|com as principais tendências','Envio Rápido|para todo o Brasil','Pagamento Facilitado|até 6x sem juros']}
 const gallery=find('gallery');gallery.title=pink?'Looks da Charmme':'Galeria da Lumière';gallery.visual={columns:3,mediaAspect:140,gap:7}
 const about=byId('about');about.title='Sobre a '+name;about.text='A '+name+' nasceu com o propósito de realçar a beleza única de cada mulher, oferecendo moda feminina moderna, elegante e versátil para todas as ocasiões. Aqui você encontra peças selecionadas com qualidade, conforto e muito estilo, para se sentir ainda mais confiante todos os dias.';about.ctaLabel='Nossa história';about.image=images.look;about.visual={mediaPlacement:'background',mediaWidth:44,mediaAspect:140,minHeight:285}
 const hours=find('hours');hours.title='Nosso Horário';const location=find('location');location.title='Nossa Localização';find('whatsapp').visual={panel:'#00963b',text:'#ffffff'};byId('copyright').text='© '+name+(pink?' Moda Feminina':' Boutique')+'. Todos os direitos reservados.'
 benefitIcons(bio)
 return {id:variant,categoryId:'fashion',label:pink?'Charmme Moda Feminina':'Lumière Boutique',subtitle:pink?'Editorial vibrante em pink: coleções, seis produtos e banner de acessórios.':'Boutique sofisticada em preto e champanhe, com composição editorial completa.',icon:'↗',bio}
}
