function benefitIcons(bio:Bio){for(const s of bio.sections.filter(s=>s.kind==='benefits')){s.entryIcons=Object.fromEntries((s.content?.benefits||[]).map((value,i)=>[entryTextKey('benefits',value),{id:s.id+'-icon-'+i,kind:'custom',label:value.split('|')[0],message:'',icon:((s.layout==='list'?['delivery','credit-card','check']:s.id.endsWith('values')?['sparkles','heart','star','beauty']:['star','delivery','credit-card','heart'])[i%4]||'heart') as Action['icon'],iconColorMode:'theme'}]))}}

